<template>
<v-app><v-navigation-drawer permanent width="240"><div class="brand"><v-icon color="primary" size="32">mdi-waves</v-icon><div>澜迹监测<small>MARINE OBSERVATORY</small></div></div><v-list nav><v-list-item prepend-icon="mdi-view-dashboard-outline" title="监控工作台" active/><v-list-item prepend-icon="mdi-map-outline" title="长江口 · 杭州湾"/><v-list-item prepend-icon="mdi-database-outline" title="MySQL 监控档案"/></v-list><div class="drawer-note">视频接入 · 目标识别 · 来源分析<br>观测范围由人工确认</div></v-navigation-drawer>
<v-app-bar flat border><v-app-bar-title>近海漂浮垃圾监测</v-app-bar-title><v-chip class="mr-6" color="primary" variant="tonal">上海近海研究区域</v-chip></v-app-bar>
<v-main><div class="workspace"><div class="heading"><div><div class="eyebrow">MONITORING WORKSPACE</div><h1>从观测到线索</h1><p>接收无人机画面，记录观测位置与时间，逐步核查可能来源。</p></div><v-btn prepend-icon="mdi-refresh" variant="outlined" @click="load">刷新记录</v-btn></div>
<v-alert v-if="error" type="error" closable class="mb-5" @click:close="error=''">{{error}}</v-alert><v-alert v-if="notice" type="success" closable class="mb-5" @click:close="notice=''">{{notice}}</v-alert>
<div class="grid"><v-card rounded="xl" flat border><v-card-title>监控记录</v-card-title><v-card-subtitle>接收文件不会自动执行识别</v-card-subtitle><v-card-text><v-tabs v-model="inputMode" class="mb-4"><v-tab value="image">图片检测</v-tab><v-tab value="video">视频接入</v-tab></v-tabs><v-file-input :label="inputMode==='image'?'选择待检测图片':'选择录像文件'" :accept="inputMode==='image'?'image/*':'video/*'" v-model="file" variant="outlined" density="compact"/><div class="actions"><v-btn color="primary" :loading="busy" :disabled="!file" @click="upload">上传并建档</v-btn><v-btn v-if="inputMode==='video'" variant="tonal" @click="stream">创建直播</v-btn></div></v-card-text><v-divider/><v-list lines="two"><v-list-item v-for="r in records" :key="r.id" :active="selected?.id===r.id" @click="select(r)" :title="r.title" :subtitle="r.media_type+' · '+r.created_at" prepend-icon="mdi-video-outline"/><div v-if="!records.length" class="empty">暂无监控记录，上传图片或视频开始。</div></v-list></v-card>
<div><v-card rounded="xl" flat border class="mb-5"><v-card-title>观测元数据</v-card-title><v-card-text v-if="selected"><v-text-field label="记录名称" v-model="form.title" variant="outlined"/><div class="two"><v-text-field label="拍摄时间（北京时间）" type="datetime-local" v-model="form.captured_at" variant="outlined"/><v-text-field label="无人机 / 设备编号" v-model="device" variant="outlined"/></div><p class="mb-3">地图点击两次圈定矩形观测区域；无人机 GPS 不直接作为垃圾位置。</p><div ref="mapEl" class="map"></div><div class="two mt-4"><v-text-field label="经度范围" v-model="lon" hint="121.2,122.5" variant="outlined"/><v-text-field label="纬度范围" v-model="lat" hint="30.5,31.6" variant="outlined"/></div><v-textarea label="自定义元数据（JSON）" v-model="metadata" rows="2" variant="outlined"/><v-btn color="primary" variant="tonal" @click="save">保存元数据</v-btn></v-card-text><div v-else class="empty">先选择或创建一条监控记录</div></v-card>
<v-card v-if="selected" rounded="xl" flat border><v-tabs v-model="tab" color="primary"><v-tab value="detect">目标识别</v-tab><v-tab value="trace">来源分析</v-tab><v-tab value="history" @click="history">识别历史</v-tab></v-tabs><v-divider/><v-card-text>
<div v-if="tab==='detect'"><div class="two"><v-text-field v-if="selected.media_type!=='IMAGE'" v-model.number="seconds" type="number" min="0" label="视频取帧时间（秒）" variant="outlined"/><v-select v-model="model" :items="['v4b','v4','v3']" label="识别模型" variant="outlined"/></div><v-btn color="primary" :loading="busy" @click="detect">{{selected.media_type==='IMAGE'?'检测图片中的垃圾':'识别当前帧'}}</v-btn><p class="caption mt-3">按帧统计数量，不将重复出现的目标累加成垃圾总数。</p><div v-if="result" class="mt-5"><svg class="preview" :viewBox="`0 0 ${result.detection.image_size[0]} ${result.detection.image_size[1]}`"><image :href="result.image" width="100%" height="100%"/><g v-for="(d,i) in result.detection.detections" :key="i"><rect :x="d.bbox_xyxy[0]" :y="d.bbox_xyxy[1]" :width="d.bbox_xyxy[2]-d.bbox_xyxy[0]" :height="d.bbox_xyxy[3]-d.bbox_xyxy[1]" fill="none" stroke="#00d084" stroke-width="2"/><text :x="d.bbox_xyxy[0]" :y="Math.max(16,d.bbox_xyxy[1]-4)" fill="#00d084" font-size="14">{{d.class_cn}} {{Math.round(d.confidence*100)}}%</text></g></svg><div class="actions mt-3"><v-chip v-for="(count,type) in counts" :key="type" color="primary">{{type}} {{count}}</v-chip><v-chip>共 {{result.detection.num_detections}} 个目标</v-chip></div></div></div>
<div v-if="tab==='trace'"><v-alert type="info" variant="tonal" class="mb-4">真实流场尚待下载和验证，当前不会生成来源排名。来源分析需要拍摄时间、观测区域与可用的历史流场。</v-alert><v-list><v-list-item v-for="s in candidates" :key="s.id" :title="s.name+' · '+s.source_type" :subtitle="s.evidence"><template #append><a :href="s.metadata.source_url" target="_blank" rel="noopener">出处</a></template></v-list-item></v-list><p class="caption mb-4">这些点位用于候选排查，不表示已确认排污。养殖区暂无核实点位，不虚构标记。</p><v-select label="垃圾类别（辅助线索）" :items="['Plastic','Glass','Metal','Trash']" v-model="garbage" variant="outlined"/><v-btn variant="tonal" @click="trace">检查溯源条件</v-btn><p v-if="traceResult" class="mt-4">{{traceResult.result.reason}}</p></div>
<v-table v-if="tab==='history'"><thead><tr><th>时间</th><th>帧位置</th><th>目标数</th><th>模型</th></tr></thead><tbody><tr v-for="r in past" :key="r.id"><td>{{r.created_at}}</td><td>{{r.frame_seconds}} 秒</td><td>{{r.result.num_detections}}</td><td>{{r.model}}</td></tr></tbody></v-table>
</v-card-text></v-card></div></div></div></v-main></v-app>
</template>
<script setup>
import {ref,computed,nextTick,onMounted} from 'vue'
import L from 'leaflet'
const inputMode=ref('image'),candidates=ref([])
const records=ref([]),selected=ref(null),form=ref({}),file=ref(null),error=ref(''),notice=ref(''),busy=ref(false),tab=ref('detect'),seconds=ref(0),model=ref('v4b'),result=ref(null),past=ref([]),garbage=ref('Plastic'),traceResult=ref(null),device=ref(''),metadata=ref('{}'),lon=ref('121.2,122.5'),lat=ref('30.5,31.6'),mapEl=ref(null)
let map,rectangle,corner
const counts=computed(()=>{const out={};for(const d of result.value?.detection.detections||[])out[d.class_cn]=(out[d.class_cn]||0)+1;return out})
async function api(path,options={}){const r=await fetch('/api'+path,options);const data=await r.json();if(!r.ok)throw new Error(data.detail||data.message||'请求失败');return data}
async function run(fn){error.value='';busy.value=true;try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function load(){await run(async()=>{records.value=await api('/records');candidates.value=await api('/candidate-sources')})}
function draw(){if(rectangle)rectangle.remove();const x=lon.value.split(',').map(Number),y=lat.value.split(',').map(Number);rectangle=L.rectangle([[y[0],x[0]],[y[1],x[1]]],{color:'#1a73e8',weight:2}).addTo(map);map.fitBounds(rectangle.getBounds())}
async function select(r){selected.value=r;form.value={...r};form.value.captured_at=(r.captured_at||'').slice(0,16);metadata.value=JSON.stringify(r.metadata||{},null,2);device.value=r.metadata?.device_id||'';const a=r.observation_area;lon.value=a?`${a.west},${a.east}`:'121.2,122.5';lat.value=a?`${a.south},${a.north}`:'30.5,31.6';result.value=null;traceResult.value=null;await nextTick();if(!map){map=L.map(mapEl.value).setView([31,121.8],9);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap'}).addTo(map);map.on('click',e=>{if(!corner){corner=e.latlng;return}lon.value=[Math.min(corner.lng,e.latlng.lng),Math.max(corner.lng,e.latlng.lng)].map(v=>v.toFixed(5)).join(',');lat.value=[Math.min(corner.lat,e.latlng.lat),Math.max(corner.lat,e.latlng.lat)].map(v=>v.toFixed(5)).join(',');corner=null;draw()})}draw();showSources()}
let sourceLayer
function showSources(){if(sourceLayer)sourceLayer.remove();sourceLayer=L.layerGroup().addTo(map);for(const s of candidates.value){const el=document.createElement('div');el.textContent=s.name+' · '+s.source_type+'（候选排查点，非排放认定）';L.circleMarker([s.latitude,s.longitude],{color:s.source_type==='港口'?'#e8710a':'#1a73e8',radius:7}).bindPopup(el).addTo(sourceLayer)}}
async function upload(){await run(async()=>{const fd=new FormData();fd.append('file',Array.isArray(file.value)?file.value[0]:file.value);const r=await api('/videos/upload',{method:'POST',body:fd});records.value=await api('/records');await select(r);notice.value='已接收，尚未执行识别'})}
async function stream(){await run(async()=>{const r=await api('/videos/streams',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:'无人机直播'})});records.value=await api('/records');await select(r.record);notice.value=r.note})}
async function save(){await run(async()=>{const x=lon.value.split(',').map(Number),y=lat.value.split(',').map(Number);if(x.length!==2||y.length!==2||![...x,...y].every(Number.isFinite)||x[0]>=x[1]||y[0]>=y[1]||x[0]<-180||x[1]>180||y[0]<-90||y[1]>90)throw new Error('请填写有效的经纬度范围');const body={title:form.value.title,captured_at:form.value.captured_at?form.value.captured_at.replace('T',' ')+':00':null,observation_area:{west:x[0],east:x[1],south:y[0],north:y[1]},metadata:{...JSON.parse(metadata.value),device_id:device.value}};selected.value=await api('/records/'+selected.value.id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});draw();notice.value='元数据已保存'})}
async function detect(){await run(async()=>result.value=await api('/detections',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({monitoring_id:selected.value.id,frame_seconds:seconds.value,model:model.value})}))}
async function trace(){await run(async()=>traceResult.value=await api('/traces',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({monitoring_id:selected.value.id,garbage_type:garbage.value})}))}
async function history(){await run(async()=>past.value=await api('/records/'+selected.value.id+'/detections'))}
onMounted(load)
</script>
<style>
body{font-family:Arial,'Microsoft YaHei',sans-serif;color:#202124}.brand{display:flex;gap:12px;align-items:center;padding:32px 20px;font-size:21px;font-weight:600}.brand small{display:block;font-size:9px;letter-spacing:1.4px;color:#80868b;margin-top:5px}.drawer-note{padding:24px;color:#80868b;font-size:12px;line-height:2}.workspace{max-width:1440px;padding:36px 40px;margin:auto}.heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:30px}.eyebrow{font-size:11px;letter-spacing:2px;color:#1a73e8;margin-bottom:10px}h1{font-size:30px;font-weight:500;letter-spacing:-1px}.heading p{color:#6b7280;margin-top:10px;font-size:14px}.grid{display:grid;grid-template-columns:340px minmax(0,1fr);gap:24px;align-items:start}.two{display:grid;grid-template-columns:1fr 1fr;gap:16px}.actions{display:flex;gap:10px;flex-wrap:wrap}.empty{padding:32px;color:#80868b;text-align:center}.map{height:260px;border-radius:14px;z-index:0}.preview{width:100%;max-height:440px;object-fit:contain;background:#f3f5f7;border-radius:12px}.caption{font-size:12px;color:#6b7280}.v-card-title{padding:22px 24px 10px!important;font-size:18px!important}.v-card-text{padding:20px 24px!important}@media(max-width:1100px){.grid{grid-template-columns:1fr}.workspace{padding:20px}.two{grid-template-columns:1fr}}
</style>
